import { FormRoot, FormFieldControl, useZodForm } from "@godxjp/ui/form";
import { Input } from "@godxjp/ui/data-entry";
import { z } from "zod";
const schema = z.object({ email: z.string().email() });
// Inside your component:
const form = useZodForm(schema, { defaultValues: { email: "" } });
<FormRoot form={form} onSubmit={save} layout="horizontal"><FormFieldControl name="email" label="Email">{field => <Input {...field} value={String(field.value ?? "")} />}</FormFieldControl></FormRoot>;
